package com.renthouse.community;import com.renthouse.auth.*;import com.renthouse.common.api.*;import com.renthouse.common.id.SnowflakeIdGenerator;import jakarta.validation.*;import jakarta.validation.constraints.*;import java.time.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/v1")public class CommunityController{private final JdbcTemplate j;private final SnowflakeIdGenerator ids;public CommunityController(JdbcTemplate j,SnowflakeIdGenerator ids){this.j=j;this.ids=ids;}@GetMapping("/community")public ApiResponse<Item>get(){return ApiResponse.ok(read());}@PutMapping("/landlord/community")public ApiResponse<Item>put(@RequestBody @Valid Request r){CurrentUser.requireRole(UserRole.LANDLORD);j.update("UPDATE community_config SET title=?,description=?,image_url=?,join_url=?,enabled=?,updated_at=? WHERE landlord_id=?",r.title(),r.description(),r.imageUrl(),r.joinUrl(),r.enabled(),LocalDateTime.now(),CurrentUser.require().id());return ApiResponse.ok(read());}@PostMapping("/community/join-events")public ApiResponse<Item>join(){long user;try{user=CurrentUser.require().id();}catch(Exception e){user=0;}j.update("INSERT INTO community_join_event(id,community_id,user_id,created_at) VALUES(?,?,?,?)",ids.nextId(),6001,user==0?null:user,LocalDateTime.now());j.update("UPDATE community_config SET member_count=member_count+1,updated_at=? WHERE id=6001 AND enabled=1",LocalDateTime.now());return ApiResponse.ok(read());}private Item read(){return j.query("SELECT title,description,image_url,join_url,enabled,member_count FROM community_config WHERE id=6001",r->r.next()?new Item(r.getString(1),r.getString(2),r.getString(3),r.getString(4),r.getBoolean(5),r.getInt(6)):null);}public record Item(String title,String description,String imageUrl,String joinUrl,boolean enabled,int memberCount){}public record Request(@NotBlank String title,String description,String imageUrl,String joinUrl,boolean enabled){}}
